// SPDX-License-Identifier: UNLICENSED
pragma solidity 0.8.36;
interface I { function one(uint256 value) external; function two(bytes32 value) external; }
contract Child { uint256 public value; constructor(uint256 initial) { value = initial; } }
contract Meta { function inspect() external pure returns (bytes memory creation, bytes memory runtime, string memory contractName, bytes4 interfaceId) { creation = type(Child).creationCode; runtime = type(Child).runtimeCode; contractName = type(Child).name; interfaceId = type(I).interfaceId; } }
